gzb(){return"\u0631\u0632\u0645\u062a\u0627\u0646 \u0645\u0646 52 \u0648\u0631\u0642\u0629\u060c \u0645\u0639 \u0627\u0644\u062c\u0648\u0643\u0631 \u0623\u0648 \u0628\u062f\u0648\u0646\u0647 (\u062e\u064a\u0627\u0631\u0643 \u0641\u064a \u0627\u0644\u063a\u0631\u0641\u0629 \u0627\u0644\u062e\u0627\u0635\u0629).\n13 \u0648\u0631\u0642\u0629 \u0644\u0643\u0644 \u0644\u0627\u0639\u0628. \u0641\u064a \u062f\u0648\u0631\u0643 \u064a\u062a\u0645 \u0627\u0644\u0633\u062d\u0628 \u062a\u0644\u0642\u0627\u0626\u064a\u064b\u0627\u060c \u062b\u0645 \u064a\u0645\u0643\u0646\u0643 \u0627\u0644\u062a\u0646\u0632\u064a\u0644\u061b \u0644\u0627 \u064a\u0648\u062c\u062f \u0631\u0645\u064a \u0644\u0644\u0648\u0631\u0642 \u0623\u0628\u062f\u064b\u0627.\n\n\u0627\u0644\u062a\u0646\u0632\u064a\u0644 \u0627\u0644\u0623\u0648\u0644: \u064a\u062c\u0628 \u0623\u0646 \u064a\u062d\u062a\u0648\u064a \u062a\u0646\u0632\u064a\u0644\u0643 \u0639\u0644\u0649 \u0645\u062a\u062a\u0627\u0644\u064a\u0629 \u062b\u0644\u0627\u062b\u064a\u0629 \u0635\u0627\u0641\u064a\u0629 \u0645\u0646 \u064a\u062f\u0643 (3 \u0623\u0648\u0631\u0627\u0642 \u0645\u062a\u062a\u0627\u0628\u0639\u0629 \u0645\u0646 \u0627\u0644\u0634\u0643\u0644 \u0646\u0641\u0633\u0647\u060c \u0628\u062f\u0648\u0646 \u062c\u0648\u0643\u0631) \u0636\u0645\u0646 \u062a\u0634\u0643\u064a\u0644\u0629 \u0648\u0627\u062d\u062f\u0629. \u0648\u0645\u0646\u0630 \u0630\u0644\u0643 \u0627\u0644\u062f\u0648\u0631 \u0646\u0641\u0633\u0647 \u064a\u0645\u0643\u0646\u0643 \u062a\u0645\u062f\u064a\u062f\u0647\u0627 (\u062d\u062a\u0649 \u0628\u062c\u0648\u0643\u0631)\u060c \u0648\u062a\u0646\u0632\u064a\u0644 \u062a\u0634\u0643\u064a\u0644\u0627\u062a \u0623\u062e\u0631\u0649\u060c \u0648\u0625\u0639\u0627\u062f\u0629 \u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u0637\u0627\u0648\u0644\u0629.\n\n\u0628\u0639\u062f \u0630\u0644\u0643 \u064a\u0645\u0643\u0646\u0643 \u0641\u064a \u0643\u0644 \u062f\u0648\u0631:\n- \u062a\u0646\u0632\u064a\u0644 \u0645\u062a\u062a\u0627\u0644\u064a\u0627\u062a (3 \u0623\u0648\u0631\u0627\u0642 \u0645\u062a\u062a\u0627\u0628\u0639\u0629 \u0623\u0648 \u0623\u0643\u062b\u0631 \u0645\u0646 \u0627\u0644\u0634\u0643\u0644 \u0646\u0641\u0633\u0647\u061b \u0627\u0644\u0622\u0633 \u064a\u0623\u062a\u064a \u0642\u0628\u0644 \u0627\u0644\u0627\u062b\u0646\u064a\u0646 \u0623\u0648 \u0628\u0639\u062f \u0627\u0644\u0645\u0644\u0643\u060c \u0644\u0643\u0646 \u0645\u0644\u0643-\u0622\u0633-2 \u0645\u0645\u0646\u0648\u0639)\u061b\n- \u062a\u0646\u0632\u064a\u0644 \u0645\u062c\u0645\u0648\u0639\u0627\u062a \u0645\u0646 \u062b\u0644\u0627\u062b \u0623\u0648 \u0623\u0631\u0628\u0639 (3-4 \u0623\u0648\u0631\u0627\u0642 \u0645\u0646 \u0627\u0644\u0631\u062a\u0628\u0629 \u0646\u0641\u0633\u0647\u0627\u060c \u0628\u0623\u0634\u0643\u0627\u0644 \u0643\u0644\u0647\u0627 \u0645\u062e\u062a\u0644\u0641\u0629)\u061b\n- \u0625\u0639\u0627\u062f\u0629 \u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u0637\u0627\u0648\u0644\u0629 \u0628\u062d\u0631\u064a\u0629\u060c \u0645\u0627 \u062f\u0627\u0645 \u0643\u0644 \u0634\u064a\u0621 \u0635\u062d\u064a\u062d\u064b\u0627 \u0639\u0646\u062f \u062a\u0623\u0643\u064a\u062f \u0627\u0644\u062a\u0646\u0632\u064a\u0644.\n\n\u0627\u0644\u062c\u0648\u0643\u0631 \u064a\u062d\u0644 \u0645\u062d\u0644 \u0623\u064a \u0648\u0631\u0642\u0629\u061b \u064a\u0645\u0643\u0646 \u0646\u0642\u0644\u0647 \u0639\u0644\u0649 \u0627\u0644\u0637\u0627\u0648\u0644\u0629\u060c \u0644\u0643\u0646\u0647 \u0644\u0627 \u064a\u0639\u0648\u062f \u0625\u0644\u0649 \u064a\u062f\u0643 \u0623\u0628\u062f\u064b\u0627.\n\n\u0623\u0648\u0644 \u0644\u0627\u0639\u0628 \u064a\u0641\u0631\u063a \u064a\u062f\u0647 \u064a\u0641\u0648\u0632 \u0628\u0627\u0644\u062c\u0648\u0644\u0629\u061b \u0648\u064a\u062d\u0633\u0628 \u0627\u0644\u0622\u062e\u0631\u0648\u0646 \u0646\u0642\u0627\u0637 \u0639\u0642\u0648\u0628\u0629 (\u0627\u0644\u0623\u0648\u0631\u0627\u0642 2-10: \u0628\u0642\u064a\u0645\u062a\u0647\u0627\u061b \u0623\u0648\u0631\u0627\u0642 \u0627\u0644\u0635\u0648\u0631: 10\u061b \u0627\u0644\u0622\u0633: 11\u061b \u0627\u0644\u062c\u0648\u0643\u0631: 50).\n\n\u062a\u0646\u062a\u0647\u064a \u0627\u0644\u0645\u0628\u0627\u0631\u0627\u0629 \u0639\u0646\u062f\u0645\u0627 \u064a\u0628\u0644\u063a \u0644\u0627\u0639\u0628 100 \u0646\u0642\u0637\u0629: \u064a\u0641\u0648\u0632 \u0635\u0627\u062d\u0628 \u0623\u0642\u0644 \u0627\u0644\u0639\u0642\u0648\u0628\u0627\u062a. \u0641\u064a \xab\u0645\u0628\u0627\u0631\u0627\u0629 \u0645\u0646 \u062c\u0648\u0644\u0629 \u0648\u0627\u062d\u062f\u0629\xbb\u060c \u0623\u0648\u0644 \u062c\u0648\u0644\u0629 \u062a\u064f\u0643\u0633\u064e\u0628 \u062a\u0646\u0647\u064a \u0627\u0644\u0645\u0628\u0627\u0631\u0627\u0629. \u062a\u064f\u062e\u062a\u0627\u0631 \u0647\u0630\u0647 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a (\u0627\u0644\u062c\u0648\u0643\u0631\u060c \u0645\u0628\u0627\u0631\u0627\u0629 \u0628\u0627\u0644\u0646\u0642\u0627\u0637 \u0623\u0648 \u0645\u0646 \u062c\u0648\u0644\u0629 \u0648\u0627\u062d\u062f\u0629) \u0639\u0646\u062f \u0625\u0646\u0634\u0627\u0621 \u063a\u0631\u0641\u0629 \u062e\u0627\u0635\u0629.\n\n\u0641\u064a \u0627\u0644\u0645\u0628\u0627\u0631\u064a\u0627\u062a \u0627\u0644\u0639\u0627\u0645\u0629: \u0627\u0644\u062c\u0648\u0643\u0631 \u062d\u0627\u0636\u0631\u060c \u0645\u0628\u0627\u0631\u0627\u0629 \u0645\u0646 \u062c\u0648\u0644\u0629 \u0648\u0627\u062d\u062f\u0629\u060c \u0648120 \u062b\u0627\u0646\u064a\u0629 \u0644\u0643\u0644 \u062f\u0648\u0631 \u2014 \u064a\u064f\u062a\u062e\u0637\u0649 \u0627\u0644\u062f\u0648\u0631 \u062a\u0644\u0642\u0627\u0626\u064a\u064b\u0627 \u0639\u0646\u062f \u0627\u0646\u062a\u0647\u0627\u0621 \u0627\u0644\u0648\u0642\u062a.\n\n\u0646\u0641\u0627\u062f \u0643\u0648\u0645\u0629 \u0627\u0644\u0633\u062d\u0628: \u062a\u062a\u0648\u0642\u0641 \u0627\u0644\u062c\u0648\u0644\u0629 \u0648\u064a\u062d\u0633\u0628 \u0643\u0644 \u0644\u0627\u0639\u0628 \u0627\u0644\u0646\u0642\u0627\u0637 \u0627\u0644\u0645\u062a\u0628\u0642\u064a\u0629 \u0641\u064a \u064a\u062f\u0647."},
gv9(){return"\u0623\u062f\u062e\u0644 \u0628\u0631\u064a\u062f\u0643 \u0627\u0644\u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a \u0648\u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631"},
go0(){return"\u062d\u0633\u0627\u0628 \u0636\u064a\u0641: \u062a\u0642\u062f\u0651\u0645\u0643 (XP\u060c \u0627\u0644\u0625\u062d\u0635\u0627\u0621\u0627\u062a\u060c \u0625\u064a\u0644\u0648) \u0645\u062d\u0641\u0648\u0638 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u062c\u0647\u0627\u0632. \u0623\u0646\u0634\u0626 \u062d\u0633\u0627\u0628\u0643 \u0644\u0644\u0627\u062d\u062a\u0641\u0627\u0638 \u0628\u0647 \u0648\u0627\u0633\u062a\u0639\u0627\u062f\u062a\u0647 \u0641\u064a \u0623\u064a \u0645\u0643\u0627\u0646."},
go4(){return"\u0627\u062d\u062a\u0641\u0638 \u0628\u062a\u0642\u062f\u0645\u0643"},
go3(){return"\u0623\u0646\u062a \u062a\u0644\u0639\u0628 \u0643\u0636\u064a\u0641: \u062a\u0642\u062f\u0645\u0643 (\u0627\u0644\u0646\u0642\u0627\u0637\u060c \u0625\u064a\u0644\u0648\u060c \u0627\u0644\u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u062a\u062c\u0645\u064a\u0644\u064a\u0629) \u0645\u0648\u062c\u0648\u062f \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u0647\u0627\u062a\u0641 \u0641\u0642\u0637. \u0623\u0646\u0634\u0626 \u062d\u0633\u0627\u0628\u0643 \u0644\u0644\u0627\u062d\u062a\u0641\u0627\u0638 \u0628\u0647 \u0648\u0627\u0644\u0639\u062b\u0648\u0631 \u0639\u0644\u0649 \u062e\u0635\u0648\u0645\u0643 \u0645\u0646 \u062c\u062f\u064a\u062f."},
go2(){return"\u062a\u0642\u062f\u0645\u0643 \u063a\u064a\u0631 \u0645\u062d\u0641\u0648\u0638. \u0623\u0646\u0634\u0626 \u062d\u0633\u0627\u0628\u0643 \u0644\u0644\u0627\u062d\u062a\u0641\u0627\u0638 \u0628\u0647."},
